def get_stock_data(ticker, exchange=None, include_snapshot=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0293000" if __import__("os").path.isdir("./environment_mix/0293000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept Z suffix
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_to_iso(dt):
        if isinstance(dt, str):
            # assume already iso
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _is_blank(s):
        return s is None or (isinstance(s, str) and s.strip() == "")

    def _make_cursor(payload_dict):
        raw = json.dumps(payload_dict, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii")

    def _log_call(status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "avreq_" + hashlib.sha256((str(time.time()) + status + str(latency_ms)).encode("utf-8")).hexdigest()[:16].upper(),
            "endpoint": "get-stock-data",
            "credential_id": None,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validation
    if not isinstance(ticker, str) or ticker.strip() == "":
        resp = _err("VALIDATION_ERROR", "ticker is required and must be a non-blank string", field="ticker")
        _log_call("error", (time.time() - t0) * 1000, {"code": resp["error"]["code"]})
        return resp
    if exchange is not None and not isinstance(exchange, str):
        resp = _err("VALIDATION_ERROR", "exchange must be a string when provided", field="exchange")
        _log_call("error", (time.time() - t0) * 1000, {"code": resp["error"]["code"]})
        return resp
    if include_snapshot is not None and not isinstance(include_snapshot, bool):
        resp = _err("VALIDATION_ERROR", "include_snapshot must be a boolean when provided", field="include_snapshot")
        _log_call("error", (time.time() - t0) * 1000, {"code": resp["error"]["code"]})
        return resp
    if include_snapshot is None:
        include_snapshot = False

    symbols = _load("symbols.json")
    if not isinstance(symbols, list):
        symbols = []

    tick = ticker.strip().upper()
    exch = exchange.strip().upper() if isinstance(exchange, str) and exchange.strip() != "" else None

    # Resolve symbol
    matches = []
    for s in symbols:
        if not isinstance(s, dict):
            continue
        if str(s.get("ticker", "")).upper() != tick:
            continue
        if exch is not None:
            if str(s.get("exchange") or "").upper() != exch:
                continue
        matches.append(s)

    if not matches:
        resp = _err("NOT_FOUND", "Symbol not found for given ticker/exchange")
        _log_call("error", (time.time() - t0) * 1000, {"code": resp["error"]["code"], "ticker": tick, "exchange": exch})
        return resp

    # If multiple, prefer active then disabled then delisted; also prefer exact exchange match when exchange not supplied? keep first stable
    status_rank = {"active": 0, "disabled": 1, "delisted": 2}
    matches.sort(key=lambda r: (status_rank.get(r.get("status"), 9), (r.get("exchange") or "")))
    symbol = matches[0]

    daily_prices = _load("daily_prices.json")
    if not isinstance(daily_prices, list):
        daily_prices = []

    sym_id = symbol.get("id")
    bars = [r for r in daily_prices if isinstance(r, dict) and r.get("symbol_id") == sym_id]
    if not bars:
        # Per tool description: NOT_FOUND when ... no data has been ingested
        resp = _err("NOT_FOUND", "No market data ingested for this symbol", symbol_id=sym_id)
        _log_call("error", (time.time() - t0) * 1000, {"code": resp["error"]["code"], "symbol_id": sym_id})
        return resp

    # Compute snapshot if requested
    snapshot_out = None
    snapshot_row = None
    stock_snapshots = _load("stock_snapshots.json")
    if not isinstance(stock_snapshots, list):
        stock_snapshots = []
    if include_snapshot:
        # Recompute from bars (most recent two closes)
        # trading_date stored as datetime; allow string parsing
        parsed = []
        for b in bars:
            td = b.get("trading_date")
            dt = _parse_dt(td) if isinstance(td, str) else None
            if dt is None and isinstance(td, (int, float)):
                # not expected; ignore
                continue
            if dt is None and isinstance(td, str):
                continue
            if dt is None and isinstance(td, datetime.datetime):
                dt = td.astimezone(datetime.timezone.utc) if td.tzinfo else td.replace(tzinfo=datetime.timezone.utc)
            if dt is None:
                # if already stored as iso-like but not parseable, skip
                continue
            parsed.append((dt, b))
        if parsed:
            parsed.sort(key=lambda x: x[0])
            last_dt, last_bar = parsed[-1]
            prev_close = None
            if len(parsed) >= 2:
                prev_close = parsed[-2][1].get("close")
            last_close = last_bar.get("close")

            # Determine snapshot status
            now = datetime.datetime.now(datetime.timezone.utc)
            ttl_hours = 24
            # Find existing snapshot row
            existing_idx = None
            for i, sr in enumerate(stock_snapshots):
                if isinstance(sr, dict) and sr.get("symbol_id") == sym_id:
                    existing_idx = i
                    snapshot_row = sr
                    break

            refreshed_at_dt = None
            if snapshot_row and snapshot_row.get("refreshed_at") is not None:
                refreshed_at_dt = _parse_dt(snapshot_row.get("refreshed_at")) if isinstance(snapshot_row.get("refreshed_at"), str) else None
            is_ttl_stale = True
            if refreshed_at_dt is not None:
                is_ttl_stale = (now - refreshed_at_dt) > datetime.timedelta(hours=ttl_hours)

            status = "fresh"
            if symbol.get("status") != "active":
                status = "stale"
            elif is_ttl_stale:
                status = "stale"
            else:
                status = "fresh"

            # Always recompute to ensure up-to-date derived fields
            day_change = None
            day_change_pct = None
            if prev_close is not None and isinstance(prev_close, (int, float)) and isinstance(last_close, (int, float)):
                day_change = float(last_close) - float(prev_close)
                if float(prev_close) > 0:
                    day_change_pct = day_change / float(prev_close)
            # Validate day_change_pct constraint range [-1, 1000] when not null
            if day_change_pct is not None:
                if day_change_pct < -1 or day_change_pct > 1000:
                    # If derived value violates constraints (e.g., bad source), drop it
                    day_change_pct = None

            now_iso = _now_iso()
            if snapshot_row is None:
                snapshot_row = {
                    "id": "avsnap_" + hashlib.sha256((sym_id + now_iso).encode("utf-8")).hexdigest()[:16].upper(),
                    "symbol_id": sym_id,
                    "as_of_date": _dt_to_iso(last_dt.replace(hour=0, minute=0, second=0, microsecond=0)),
                    "last_close": float(last_close) if isinstance(last_close, (int, float)) else 0.0,
                    "prev_close": float(prev_close) if isinstance(prev_close, (int, float)) else None,
                    "day_change": day_change,
                    "day_change_pct": day_change_pct,
                    "status": status,
                    "refreshed_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso
                }
                stock_snapshots.append(snapshot_row)
            else:
                # Transition allowed between any except constraints; enforce lifecycle transitions
                old_status = snapshot_row.get("status")
                allowed = {
                    "unavailable": ["fresh", "stale"],
                    "stale": ["fresh", "unavailable"],
                    "fresh": ["stale", "unavailable"]
                }
                if old_status in allowed and status != old_status and status not in allowed.get(old_status, []):
                    resp = _err("INVALID_TRANSITION", f"Cannot transition snapshot status from {old_status} to {status}")
                    _log_call("error", (time.time() - t0) * 1000, {"code": resp["error"]["code"], "symbol_id": sym_id})
                    return resp

                snapshot_row["as_of_date"] = _dt_to_iso(last_dt.replace(hour=0, minute=0, second=0, microsecond=0))
                snapshot_row["last_close"] = float(last_close) if isinstance(last_close, (int, float)) else snapshot_row.get("last_close", 0.0)
                snapshot_row["prev_close"] = float(prev_close) if isinstance(prev_close, (int, float)) else None
                snapshot_row["day_change"] = day_change
                snapshot_row["day_change_pct"] = day_change_pct
                snapshot_row["status"] = status
                snapshot_row["refreshed_at"] = now_iso
                snapshot_row["updated_at"] = now_iso
                stock_snapshots[existing_idx] = snapshot_row

            _save("stock_snapshots.json", stock_snapshots)
            snapshot_out = snapshot_row
        else:
            # No parseable bars; treat as no data
            resp = _err("NOT_FOUND", "No market data ingested for this symbol", symbol_id=sym_id)
            _log_call("error", (time.time() - t0) * 1000, {"code": resp["error"]["code"], "symbol_id": sym_id})
            return resp

    resp = {
        "symbol": symbol,
        "snapshot": snapshot_out if include_snapshot else None
    }
    _log_call("ok", (time.time() - t0) * 1000, {"symbol_id": sym_id, "include_snapshot": include_snapshot})
    return resp

def get_stock_alerts(symbol_id=None, ticker=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0293000" if __import__("os").path.isdir("./environment_mix/0293000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # ---- rate limiting / request logging helpers ----
    def _parse_dt(val):
        if val is None:
            return None
        if isinstance(val, datetime.datetime):
            return val if val.tzinfo else val.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(val, str):
            return None
        s = val.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, params, status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row_id = "avreq_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
        logs.append({
            "id": row_id,
            "endpoint": endpoint,
            "params": params,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now.isoformat()
        })
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rpm = cfg.get("rate_limit_per_minute")
            qpd = cfg.get("quota_per_day")
        else:
            rpm = None
            qpd = None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff_min = now - datetime.timedelta(minutes=1)
        cutoff_day = now - datetime.timedelta(days=1)

        def _count_since(dt_cut):
            c = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != endpoint:
                    continue
                rdt = _parse_dt(r.get("created_at"))
                if rdt and rdt >= dt_cut:
                    c += 1
            return c

        if isinstance(rpm, int) and rpm >= 0:
            if _count_since(cutoff_min) >= rpm:
                _log(endpoint, {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 429, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(qpd, int) and qpd >= 0:
            if _count_since(cutoff_day) >= qpd:
                _log(endpoint, {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 429, "QUOTA_EXCEEDED")
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    lim_err = _enforce_limits("get-stock-alerts")
    if lim_err:
        return lim_err

    # ---- validations ----
    if symbol_id is not None:
        if not isinstance(symbol_id, str) or not re.match(r"^avsym_[0-9A-Z]+$", symbol_id):
            _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid symbol_id format.", field="symbol_id")

    if ticker is not None and not isinstance(ticker, str):
        _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ticker must be a string.", field="ticker")

    allowed_status = {"active", "acknowledged", "expired"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported status value.", field="status", allowed=sorted(list(allowed_status)))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")

    allowed_sort = {"created_at", "-created_at", "triggered_on_date", "-triggered_on_date"}
    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort value.", field="sort", allowed=sorted(list(allowed_sort)))

    # cursor handling: base64url(JSON: {"o": int})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or "o" not in obj or not isinstance(obj["o"], int) or obj["o"] < 0:
                raise ValueError("bad token")
            offset = obj["o"]
        except Exception:
            _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is not a valid pagination token.", field="cursor")

    # ---- resolve symbol filter ----
    symbols = _load("symbols.json")
    sym_row = None
    if symbol_id is not None:
        for s in symbols:
            if isinstance(s, dict) and s.get("id") == symbol_id:
                sym_row = s
                break
        if sym_row is None:
            # well-formed read: empty result set
            resp = {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}
            _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 200, None)
            return resp
    elif ticker is not None:
        t = ticker.strip()
        for s in symbols:
            if isinstance(s, dict) and isinstance(s.get("ticker"), str) and s.get("ticker").upper() == t.upper():
                sym_row = s
                break
        if sym_row is None:
            resp = {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}
            _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 200, None)
            return resp

    # ---- load and filter alerts ----
    alerts = _load("alerts.json")
    if not isinstance(alerts, list):
        alerts = []

    filtered = []
    for a in alerts:
        if not isinstance(a, dict):
            continue
        if sym_row is not None and a.get("symbol_id") != sym_row.get("id"):
            continue
        if status is not None:
            if a.get("status") != status:
                continue
        else:
            # business rule: default active only
            if a.get("status") != "active":
                continue
        filtered.append(a)

    # ---- sort ----
    field = "created_at" if "created_at" in sort else "triggered_on_date"
    desc = sort.startswith("-")

    def _key(row):
        dt = _parse_dt(row.get(field))
        # stable ordering with id as tiebreaker
        return (dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), str(row.get("id") or ""))

    filtered.sort(key=_key, reverse=desc)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        token = json.dumps({"o": next_off}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("ascii").rstrip("=")

    # ---- join symbol fields (lightweight) ----
    sym_by_id = {}
    for s in symbols:
        if isinstance(s, dict) and isinstance(s.get("id"), str):
            sym_by_id[s["id"]] = s

    out = []
    for a in page:
        s = sym_by_id.get(a.get("symbol_id"))
        row = dict(a)
        if isinstance(s, dict):
            row["symbol"] = {"id": s.get("id"), "ticker": s.get("ticker"), "exchange": s.get("exchange"), "status": s.get("status")}
        out.append(row)

    resp = {"data": out, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
    _log("get-stock-alerts", {"symbol_id": symbol_id, "ticker": ticker, "status": status, "limit": limit, "cursor": cursor, "sort": sort}, 200, None)
    return resp

def get_daily_stock_data(symbol_id=None, ticker=None, start_date=None, end_date=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0293000" if __import__("os").path.isdir("./environment_mix/0293000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt_str(val, field):
        if val is None:
            return None, None
        if not isinstance(val, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string.", field=field)
        s = val.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"Invalid datetime format for {field}.", field=field)

    # ---- request logging / rate limiting ----
    def _parse_dt(val):
        if val is None:
            return None
        if isinstance(val, datetime.datetime):
            return val if val.tzinfo else val.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(val, str):
            return None
        s = val.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, params, status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row_id = "avreq_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
        logs.append({
            "id": row_id,
            "endpoint": endpoint,
            "params": params,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now.isoformat()
        })
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rpm = cfg.get("rate_limit_per_minute")
            qpd = cfg.get("quota_per_day")
        else:
            rpm = None
            qpd = None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff_min = now - datetime.timedelta(minutes=1)
        cutoff_day = now - datetime.timedelta(days=1)

        def _count_since(dt_cut):
            c = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != endpoint:
                    continue
                rdt = _parse_dt(r.get("created_at"))
                if rdt and rdt >= dt_cut:
                    c += 1
            return c

        if isinstance(rpm, int) and rpm >= 0:
            if _count_since(cutoff_min) >= rpm:
                _log(endpoint, {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 429, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(qpd, int) and qpd >= 0:
            if _count_since(cutoff_day) >= qpd:
                _log(endpoint, {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 429, "QUOTA_EXCEEDED")
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    lim_err = _enforce_limits("get-daily-stock-data")
    if lim_err:
        return lim_err

    # ---- validations ----
    if symbol_id is not None:
        if not isinstance(symbol_id, str) or not re.match(r"^avsym_[0-9A-Z]+$", symbol_id):
            _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid symbol_id format.", field="symbol_id")

    if ticker is not None and not isinstance(ticker, str):
        _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ticker must be a string.", field="ticker")

    if limit is None:
        limit = 500
    if not isinstance(limit, int) or limit < 1 or limit > 5000:
        _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range (1..5000).", field="limit")

    allowed_sort = {"trading_date", "-trading_date"}
    if sort is None:
        sort = "-trading_date"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort value.", field="sort", allowed=sorted(list(allowed_sort)))

    start_dt, e1 = _parse_dt_str(start_date, "start_date")
    if e1:
        _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
        return e1
    end_dt, e2 = _parse_dt_str(end_date, "end_date")
    if e2:
        _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
        return e2

    # cursor handling: base64url(JSON: {"o": int})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or "o" not in obj or not isinstance(obj["o"], int) or obj["o"] < 0:
                raise ValueError("bad token")
            offset = obj["o"]
        except Exception:
            _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is not a valid pagination token.", field="cursor")

    # ---- resolve symbol ----
    symbols = _load("symbols.json")
    sym_row = None
    if symbol_id is not None:
        for s in symbols:
            if isinstance(s, dict) and s.get("id") == symbol_id:
                sym_row = s
                break
        if sym_row is None:
            resp = {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}
            _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 200, None)
            return resp
    elif ticker is not None:
        t = ticker.strip()
        for s in symbols:
            if isinstance(s, dict) and isinstance(s.get("ticker"), str) and s.get("ticker").upper() == t.upper():
                sym_row = s
                break
        if sym_row is None:
            resp = {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}
            _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 200, None)
            return resp
    else:
        # If no symbol specified, return empty set (vendor endpoint usually requires symbol; here keep safe)
        resp = {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}
        _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 200, None)
        return resp

    # ---- fetch bars ----
    daily = _load("daily_prices.json")
    if not isinstance(daily, list):
        daily = []

    def _row_dt(r):
        v = r.get("trading_date")
        dt = _parse_dt(v)
        return dt

    rows = []
    for r in daily:
        if not isinstance(r, dict):
            continue
        if r.get("symbol_id") != sym_row.get("id"):
            continue
        dt = _row_dt(r)
        if dt is None:
            continue
        if start_dt is not None and dt < start_dt:
            continue
        if end_dt is not None and dt > end_dt:
            continue
        rows.append(r)

    # Business rule: if no daily_prices exist for an active symbol, may enqueue job depending on config
    if len(rows) == 0 and sym_row.get("status") == "active":
        cfg = _load("service_config.json")
        should_enqueue = False
        if isinstance(cfg, dict):
            should_enqueue = bool(cfg.get("enqueue_on_cache_miss", False))
        if should_enqueue:
            jobs = _load("ingestion_jobs.json")
            if not isinstance(jobs, list):
                jobs = []

            # idempotency: don't enqueue if an active queued/running refresh_symbol_daily exists for this symbol
            already = False
            for j in jobs:
                if not isinstance(j, dict):
                    continue
                if j.get("job_type") == "refresh_symbol_daily" and j.get("symbol_id") == sym_row.get("id") and j.get("status") in ("queued", "running"):
                    already = True
                    break

            if not already:
                jid = "avjob_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
                ts = now.isoformat()
                jobs.append({
                    "id": jid,
                    "job_type": "refresh_symbol_daily",
                    "symbol_id": sym_row.get("id"),
                    "requested_at": ts,
                    "started_at": None,
                    "finished_at": None,
                    "status": "queued",
                    "alpha_vantage_endpoint": "TIME_SERIES_DAILY",
                    "http_status_code": None,
                    "error_code": None,
                    "error_message": None,
                    "rows_upserted": 0,
                    "created_at": ts,
                    "updated_at": ts
                })
                _save("ingestion_jobs.json", jobs)

    # sort
    desc = sort.startswith("-")
    rows.sort(key=lambda r: (_row_dt(r) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), str(r.get("id") or "")), reverse=desc)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        token = json.dumps({"o": next_off}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("ascii").rstrip("=")

    # join symbol
    out = []
    sym_info = {"id": sym_row.get("id"), "ticker": sym_row.get("ticker"), "exchange": sym_row.get("exchange"), "status": sym_row.get("status")}
    for r in page:
        rr = dict(r)
        rr["symbol"] = sym_info
        out.append(rr)

    resp = {"data": out, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
    _log("get-daily-stock-data", {"symbol_id": symbol_id, "ticker": ticker, "start_date": start_date, "end_date": end_date, "limit": limit, "cursor": cursor, "sort": sort}, 200, None)
    return resp

def get_symbols(ticker=None, exchange=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0293000" if __import__("os").path.isdir("./environment_mix/0293000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if not isinstance(tok, str) or not tok.strip():
            return None
        t = tok.strip()
        pad = "=" * ((4 - (len(t) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((t + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj
        except Exception:
            return None

    # ---- Validate inputs (before any DB mutations other than request logging) ----
    if ticker is not None and not isinstance(ticker, str):
        return _err("VALIDATION_ERROR", "ticker must be a string")
    if exchange is not None and not isinstance(exchange, str):
        return _err("VALIDATION_ERROR", "exchange must be a string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "disabled", "delisted"):
            return _err("VALIDATION_ERROR", "Unsupported status value", allowed=["active", "disabled", "delisted"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit out of range", minimum=1, maximum=200)
    if sort is None:
        sort = "ticker"
    if not isinstance(sort, str):
        return _err("VALIDATION_ERROR", "sort must be a string")
    allowed_sort = ("created_at", "-created_at", "ticker", "-ticker", "updated_at", "-updated_at")
    if sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Unsupported sort value", allowed=list(allowed_sort))
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    cur = None
    if cursor:
        cur = _decode_cursor(cursor)
        if not isinstance(cur, dict) or "offset" not in cur or "sort" not in cur or "filters" not in cur:
            return _err("VALIDATION_ERROR", "Invalid cursor token")
        if cur.get("sort") != sort:
            return _err("VALIDATION_ERROR", "Cursor sort does not match requested sort")
        # ensure filters match to avoid confusing pagination
        expected_filters = {
            "ticker": ticker if ticker is None else ticker,
            "exchange": exchange if exchange is None else exchange,
            "status": status if status is None else status,
        }
        if cur.get("filters") != expected_filters:
            return _err("VALIDATION_ERROR", "Cursor filters do not match requested filters")
        if not isinstance(cur.get("offset"), int) or cur["offset"] < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor token")
    offset = cur["offset"] if cur else 0

    # ---- Read + filter ----
    symbols = _load("symbols.json")

    def _match(sym):
        if not isinstance(sym, dict):
            return False
        if ticker is not None and sym.get("ticker") != ticker:
            return False
        if exchange is not None and sym.get("exchange") != exchange:
            return False
        if status is not None and sym.get("status") != status:
            return False
        return True

    filtered = [s for s in symbols if _match(s)]

    # ---- Sort ----
    reverse = sort.startswith("-")
    key = sort[1:] if reverse else sort

    def _keyval(s):
        v = s.get(key)
        if key in ("created_at", "updated_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        # ticker: normalize None to empty string for deterministic ordering
        if v is None:
            return ""
        if isinstance(v, str):
            return v.upper()
        return str(v)

    # Stable tie-breaker by id for deterministic pagination
    def _sort_tuple(s):
        return (_keyval(s), (s.get("id") or ""))

    filtered.sort(key=_sort_tuple, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"offset": next_offset, "sort": sort, "filters": {"ticker": ticker, "exchange": exchange, "status": status}}) if has_more else None

    # ---- Request logging (observable dynamics) ----
    # Best-effort: if request_logs.json does not exist, we create/append.
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    latency_ms = int((time.time() - _t0) * 1000)
    logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": "get-symbols",
        "credential_id": None,
        "status": "succeeded",
        "http_status": 200,
        "latency_ms": latency_ms,
        "timestamp": _now_iso(),
        "request": {"ticker": ticker, "exchange": exchange, "status": status, "limit": limit, "cursor": cursor, "sort": sort},
        "response_meta": {"returned": len(page), "total": total, "has_more": has_more}
    })
    _save("request_logs.json", logs)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort
        }
    }

def create_alert_rule(symbol_id, rule_type, is_recurring, threshold_number=None, threshold_integer=None, cooldown_minutes=None, status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0293000" if __import__("os").path.isdir("./environment_mix/0293000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-alert-rule"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _ensure_list_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        return obj if isinstance(obj, list) else []

    def _log(status_code, error_code=None):
        logs = _load("request_logs.json")
        logs = _ensure_list_rows(logs)
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential_used": None,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        })
        _save("request_logs.json", logs)

    # ---- Validate inputs (types/enums/ranges) ----
    if not isinstance(symbol_id, str) or not symbol_id:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol_id must be a non-empty string")
    if not symbol_id.startswith("avsym_"):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol_id must match pattern ^avsym_[0-9A-Z]+$")

    allowed_rule_types = ["price_above", "price_below", "pct_change_above", "pct_change_below", "volume_above"]
    if not isinstance(rule_type, str) or rule_type not in allowed_rule_types:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "rule_type must be one of the supported values", allowed=allowed_rule_types)

    if not isinstance(is_recurring, bool):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_recurring must be a boolean")

    if cooldown_minutes is None:
        cooldown_minutes = 0
    if not isinstance(cooldown_minutes, int):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cooldown_minutes must be an integer")
    if cooldown_minutes < 0 or cooldown_minutes > 525600:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cooldown_minutes must be between 0 and 525600 inclusive")

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "paused"):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be 'active' or 'paused'")

    # Threshold basic type checks
    if threshold_number is not None and not isinstance(threshold_number, (int, float)):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "threshold_number must be a number when provided")
    if threshold_integer is not None and not isinstance(threshold_integer, int):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "threshold_integer must be an integer when provided")
    if threshold_number is not None and threshold_number < 0:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "threshold_number must be >= 0")
    if threshold_integer is not None and threshold_integer < 0:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "threshold_integer must be >= 0")

    # ---- Validate symbol exists and is active (business rule) ----
    symbols = _ensure_list_rows(_load("symbols.json"))
    sym = None
    for s in symbols:
        if isinstance(s, dict) and s.get("id") == symbol_id:
            sym = s
            break
    if sym is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "symbol_id does not exist", symbol_id=symbol_id)
    if sym.get("status") != "active":
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Cannot create alert rule: referenced symbol is not active (business rule)", symbol_status=sym.get("status"))

    # ---- Threshold business rule (relaxed vs old broken behavior) ----
    # Schema constraint requires exactly one threshold field depending on rule_type.
    # However, audit indicates real service accepts requests that include an extra threshold field
    # as long as the required one is present. Therefore: enforce presence of required threshold,
    # but ignore/clear the irrelevant one instead of rejecting.
    if rule_type == "volume_above":
        if threshold_integer is None:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Rule type 'volume_above' requires threshold_integer (business rule)")
        # ignore threshold_number if provided
        threshold_number = None
    else:
        if threshold_number is None:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Rule type '{rule_type}' requires threshold_number (business rule)")
        # ignore threshold_integer if provided
        threshold_integer = None

    # ---- Create row ----
    alert_rules_obj = _load("alert_rules.json")
    alert_rules = _ensure_list_rows(alert_rules_obj)

    # generate id with correct prefix
    new_id = f"avalert_rule_{int(time.time()*1000):013d}{os.getpid():05d}".upper()
    now_iso = _now_iso()
    row = {
        "id": new_id,
        "symbol_id": symbol_id,
        "rule_type": rule_type,
        "threshold_number": float(threshold_number) if threshold_number is not None else None,
        "threshold_integer": int(threshold_integer) if threshold_integer is not None else None,
        "is_recurring": bool(is_recurring),
        "cooldown_minutes": int(cooldown_minutes),
        "last_triggered_at": None,
        "status": status,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    alert_rules.append(row)

    # Preserve file shape (list vs {"rows": [...]})
    if isinstance(alert_rules_obj, dict) and "rows" in alert_rules_obj and isinstance(alert_rules_obj["rows"], list):
        alert_rules_obj["rows"] = alert_rules
        _save("alert_rules.json", alert_rules_obj)
    else:
        _save("alert_rules.json", alert_rules)

    _log(201, None)
    return {"alert_rule": row}

