        if cooldown_minutes < 0 or cooldown_minutes > 525600:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cooldown_minutes must be between 0 and 525600")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "paused", "deleted"):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, paused, deleted")

    # ---- Load and find rule ----
    rules = _load("alert_rules.json")
    if isinstance(rules, dict) and "rows" in rules and isinstance(rules["rows"], list):
        rules = rules["rows"]
    if not isinstance(rules, list):
        rules = []

    idx = None
    rule = None
    for i, r in enumerate(rules):
        if isinstance(r, dict) and r.get("id") == alert_rule_id:
            idx, rule = i, r
            break
    if rule is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Alert rule not found")

    # ---- Enforce lifecycle transitions ----
    cur_status = rule.get("status")
    transitions = {
        "active": set(["paused", "deleted"]),
        "paused": set(["active", "deleted"]),
        "deleted": set([])
    }
    if status is not None:
        if cur_status not in transitions:
            _log(409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Unknown current status {cur_status}")
        if status != cur_status and status not in transitions[cur_status]:
            _log(409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition alert rule from {cur_status} to {status}")
        if cur_status == "deleted" and status != "deleted":
            _log(409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot modify a deleted alert rule")

    # ---- Apply updates ----
    updated = dict(rule)
    if threshold_number is not None:
        updated["threshold_number"] = float(threshold_number)
    if threshold_integer is not None:
        updated["threshold_integer"] = int(threshold_integer)
    if is_recurring is not None:
        updated["is_recurring"] = is_recurring
    if cooldown_minutes is not None:
        updated["cooldown_minutes"] = int(cooldown_minutes)
    if status is not None:
        updated["status"] = status

    # ---- Enforce threshold-field constraint based on existing rule_type ----
    rt = updated.get("rule_type")
    if rt in ("price_above", "price_below", "pct_change_above", "pct_change_below"):
        if updated.get("threshold_number") is None or updated.get("threshold_integer") is not None:
            _log(400, "VALIDATION_ERROR")
            return _err(
                "VALIDATION_ERROR",
                "Invalid threshold fields for rule_type: requires threshold_number and forbids threshold_integer"
            )
    elif rt == "volume_above":
        if updated.get("threshold_integer") is None or updated.get("threshold_number") is not None:
            _log(400, "VALIDATION_ERROR")
            return _err(
                "VALIDATION_ERROR",
                "Invalid threshold fields for rule_type: requires threshold_integer and forbids threshold_number"
            )
    else:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Stored rule has unsupported rule_type", rule_type=rt)

    # ---- Business rule: referenced symbol must still be active for active rules (allow paused/deleted regardless) ----
    if updated.get("status") == "active":
        symbols = _load("symbols.json")
        if isinstance(symbols, dict) and "rows" in symbols and isinstance(symbols["rows"], list):
            symbols = symbols["rows"]
        if not isinstance(symbols, list):
            symbols = []
        sym = None
        for s in symbols:
            if isinstance(s, dict) and s.get("id") == updated.get("symbol_id"):
                sym = s
                break
        if sym is None:
            _log(409, "CONFLICT")
            return _err("CONFLICT", "Referenced symbol no longer exists")
        if sym.get("status") != "active":
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Referenced symbol is not active", symbol_status=sym.get("status"))

    # ---- Persist ----
    updated["updated_at"] = _now_iso()
    rules[idx] = updated
    _save("alert_rules.json", rules)
    _log(200, None)
    return {"alert_rule": updated}

def acknowledge_stock_alert(alert_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0293000" if __import__("os").path.isdir("./environment_mix/0293000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "acknowledge-stock-alert"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _ensure_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        return obj if isinstance(obj, list) else []

    def _write_back(filename, original_obj, rows):
        if isinstance(original_obj, dict) and isinstance(original_obj.get("rows"), list):
            original_obj["rows"] = rows
            _save(filename, original_obj)
        else:
            _save(filename, rows)

    def _append_request_log(status, error_code=None):
        # Record every call if the log collection exists; create it if missing.
        logs_obj = _load("request_logs.json")
        logs = _ensure_rows(logs_obj)
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential_used": None,
            "status": int(status),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        })
        if isinstance(logs_obj, dict) and isinstance(logs_obj.get("rows"), list):
            logs_obj["rows"] = logs
            _save("request_logs.json", logs_obj)
        else:
            _save("request_logs.json", logs)

    # ---------- Validate inputs ----------
    if not isinstance(alert_id, str) or not alert_id.strip():
        _append_request_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "alert_id must be a non-empty string", alert_id=alert_id)

    alert_id = alert_id.strip()
    if not re.match(r"^avalert_[0-9A-Z]+$", alert_id):
        # Enforce declared parameter schema: reject ids that cannot be valid alert ids.
        _append_request_log(400, "VALIDATION_ERROR")
        return _err(
            "VALIDATION_ERROR",
            "alert_id must match pattern ^avalert_[0-9A-Z]+$ (alerts.id)",
            alert_id=alert_id
        )

    # ---------- Load alerts ----------
    alerts_obj = _load("alerts.json")
    alerts = _ensure_rows(alerts_obj)

    idx = None
    alert = None
    for i, a in enumerate(alerts):
        if isinstance(a, dict) and a.get("id") == alert_id:
            idx, alert = i, a
            break

    if alert is None:
        # Business-rule: the id must correspond to an existing alert row.
        _append_request_log(404, "NOT_FOUND")
        return _err(
            "NOT_FOUND",
            "Alert not found: alert_id does not correspond to an existing alerts row.",
            alert_id=alert_id
        )

    # ---------- Enforce lifecycle transition rules ----------
    status = alert.get("status")
    if status != "active":
        # Refuse when alert isn't currently active (already acknowledged or expired).
        _append_request_log(409, "INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "Only active alerts can be acknowledged (business rule: alerts.status must transition from 'active' to 'acknowledged' only).",
            alert_id=alert_id,
            current_status=status,
            allowed_transition="active -> acknowledged"
        )

    # Perform transition
    now = _now_iso()
    updated = dict(alert)
    updated["status"] = "acknowledged"
    updated["updated_at"] = now

    # Persist
    alerts[idx] = updated
    _write_back("alerts.json", alerts_obj, alerts)

    _append_request_log(200, None)
    return {"alert": updated}

def create_ingestion_job(job_type, symbol_id, alpha_vantage_endpoint=None, **_extra):
    import json, os, datetime, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0293000" if __import__("os").path.isdir("./environment_mix/0293000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        alphabet = string.digits + string.ascii_uppercase
        return prefix + "".join(random.choice(alphabet) for _ in range(12))

    def _final(resp):
        return resp

    if not isinstance(job_type, str) or job_type not in ("refresh_symbol_daily",):
        return _final(_err("VALIDATION_ERROR", "Invalid job_type; allowed: refresh_symbol_daily."))
    if not isinstance(symbol_id, str) or not symbol_id or not symbol_id.startswith("avsym_"):
        return _final(_err("VALIDATION_ERROR", "Invalid symbol_id. Expected pattern ^avsym_[0-9A-Z]+$."))

    if alpha_vantage_endpoint is not None:
        if not isinstance(alpha_vantage_endpoint, str) or alpha_vantage_endpoint not in ("TIME_SERIES_DAILY_ADJUSTED", "TIME_SERIES_DAILY"):
            return _final(_err("VALIDATION_ERROR", "Invalid alpha_vantage_endpoint."))

    symbols = _load("symbols.json")
    sym = next((r for r in symbols if isinstance(r, dict) and r.get("id") == symbol_id), None)
    if not sym:
        return _final(_err("NOT_FOUND", "Symbol not found."))
    if sym.get("status") == "delisted":
        return _final(_err("VALIDATION_ERROR", "Cannot start ingestion for a delisted symbol."))

    jobs = _load("ingestion_jobs.json")

    now = _now()
    new_id = _gen_id("aving_")
    existing_ids = {r.get("id") for r in jobs if isinstance(r, dict)}
    while new_id in existing_ids:
        new_id = _gen_id("aving_")

    job = {
        "id": new_id,
        "job_type": job_type,
        "symbol_id": symbol_id,
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "status": "queued",
        "alpha_vantage_endpoint": alpha_vantage_endpoint,
        "http_status_code": None,
        "error_code": None,
        "error_message": None,
        "rows_upserted": 0,
        "created_at": now,
        "updated_at": now
    }

    jobs.append(job)
    _save("ingestion_jobs.json", jobs)

    return _final({"ingestion_job": job})
